package org.apache.shardingsphere.tmp;

import org.apache.shardingsphere.sql.parser.api.CacheOption;
import org.apache.shardingsphere.sql.parser.api.SQLParserEngine;
import org.apache.shardingsphere.sql.parser.api.SQLStatementVisitorEngine;
import org.apache.shardingsphere.sql.parser.core.ParseASTNode;
import org.apache.shardingsphere.sql.parser.sql.common.statement.SQLStatement;
import org.apache.shardingsphere.sql.parser.sql.dialect.handler.dml.InsertStatementHandler;
import org.apache.shardingsphere.sql.parser.sql.common.statement.dml.InsertStatement;
import org.junit.jupiter.api.Test;

public class TempParseTest {

    private SQLStatement parse(final String sql) {
        SQLParserEngine parserEngine = new SQLParserEngine("SQLServer", new CacheOption(128, 1024L));
        ParseASTNode ast = parserEngine.parse(sql, false);
        return new SQLStatementVisitorEngine("SQLServer").visit(ast);
    }

    @Test
    void run() {
        String[] sqls = {
            "INSERT INTO t_order WITH (TABLOCK) SELECT * FROM t_source",
            "INSERT INTO t_order WITH (TABLOCK, HOLDLOCK) SELECT order_id FROM t_source",
            "INSERT INTO dbo.t_order EXEC proc_name @a = 1, @b = 'x'",
            "SELECT CAST(SERVERPROPERTY('ProductVersion') AS INT) * 2 AS v FROM t_order",
            "SELECT o.id, COUNT(*) AS c FROM t_order o JOIN t_item i ON o.id = i.order_id "
                + "WHERE o.name LIKE '%a%' AND o.status = 1 GROUP BY o.id HAVING COUNT(*) > 1 ORDER BY o.id",
        };
        for (String sql : sqls) {
            try {
                SQLStatement statement = parse(sql);
                String extra = "";
                if (statement instanceof InsertStatement) {
                    extra = " withTableHint=" + InsertStatementHandler.getWithTableHintSegment((InsertStatement) statement)
                            .map(h -> h.getTableHintLimitedSegments().toString()).orElse("none")
                            + " exec=" + InsertStatementHandler.getExecSegment((InsertStatement) statement).isPresent();
                }
                System.out.println("OK  :: " + statement.getClass().getSimpleName() + extra + " :: " + sql);
            } catch (RuntimeException ex) {
                System.out.println("FAIL:: " + ex.getClass().getSimpleName() + ": " + ex.getMessage() + " :: " + sql);
            }
        }
    }
}
